import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    a = sorted(int(x) for x in data[1:1 + n])
    res = []
    for i in range(n - 2):
        if a[i] > 0:
            break
        if i and a[i] == a[i - 1]:
            continue
        l, r = i + 1, n - 1
        while l < r:
            s = a[i] + a[l] + a[r]
            if s < 0:
                l += 1
            elif s > 0:
                r -= 1
            else:
                res.append((a[i], a[l], a[r]))
                l += 1
                r -= 1
                while l < r and a[l] == a[l - 1]:
                    l += 1
                while l < r and a[r] == a[r + 1]:
                    r -= 1
    out = [str(len(res))] + [' '.join(map(str, t)) for t in res]
    print('\n'.join(out))

